&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Nurture and grow the relationships within the assigned accounts, ensuring frequent contact with key clients, in-person meetings and social gatherings&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Project management of small to medium projects/retainers, owning the coordination and completion of project timelines, resourcing, delivery, change requests, budget, and perform agile ceremonies as required &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Be the escalation point of contact, ensuring problems are solved efficiently and with minimal impact to the client relationship, internal team and quality of work&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Conduct/assist workshops and discovery sessions to capture business and functional requirements of assigned accounts, to inform new opportunities and the scoping of identified opportunities&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Manage the resourcing of accounts, ensuring accounts are adequately and efficiently resourced&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Maintain and demonstrate a sound knowledge of Ogilvy One’s range of technical, strategic and campaign service offerings, to answer client enquiries and to proactively seek new opportunities by identifying accounts&#39; needs within Ogilvy One’s service offerings&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Build and maintain relationships across platform partners (e.g. Martech Account Executives) to share knowledge and seek new opportunities&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;Lead the end-to-end execution of marketing campaigns (primarily email marketing), including creative development, strategic guidance, quality assurance, deployment, and reporting&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;WHAT YOU&#39;LL BRING:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Demonstrated experience with strong stakeholder management to deliver successful outcomes &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Solid understanding of marketing technology and digital marketing&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in overseeing and managing campaigns end to end&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Familiarity with digital campaigns, including email campaigns and lifecycle communications&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Comfortable presenting campaign findings to stakeholders to drive continuous improvement &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong ability to triage and work with both internal and external stakeholders to ensure outcomes&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong organisation and project management skills&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excellent written and verbal communication skills with attention to detail&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Exceptional relationship-building skills and a team player mentality&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Be comfortable with simplifying complex technical strategies and requirements to nontechnical stakeholders&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience identifying opportunities to add value to existing tech stacks &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;ABOUT OGILVY ONE&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ogilvy One is the customer experience and engagement arm of Ogilvy, specialising in building valuable relationships by design.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For 25 years, we&#39;ve transformed business challenges into human-centric solutions that drive long-term customer value, always putting creativity at the heart of our approach. Across Ogilvy&#39;s global network of 120+ offices, we combine creativity, data, and AI to craft personalised brand experiences that connect with customers on a deeper level.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;With over 4,000 specialists bringing expertise in creative, strategy, data, media, and technology, supported by a network of technology hubs powered by Verticurl, we deliver integrated solutions that help brands thrive in the age of personalisation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h4 class=&quot;PDq2pG_selectionAnchorContainer&quot; data-section-id=&quot;1m2c87q&quot; data-start=&quot;0&quot; data-end=&quot;26&quot;&gt;WHY YOU&#39;LL LOVE OGILVY&lt;/h4&gt;
&lt;ul&gt;
&lt;li data-section-id=&quot;gle8yc&quot; data-start=&quot;28&quot; data-end=&quot;140&quot;&gt;&lt;strong data-start=&quot;30&quot; data-end=&quot;54&quot;&gt;Global opportunities&lt;/strong&gt; – Access career pathways, projects and connections across the Ogilvy and WPP network.&lt;/li&gt;
&lt;li data-section-id=&quot;6ccue8&quot; data-start=&quot;141&quot; data-end=&quot;230&quot;&gt;&lt;strong data-start=&quot;143&quot; data-end=&quot;175&quot;&gt;16 weeks paid parental leave&lt;/strong&gt; – Gender-neutral leave for all parents and caregivers.&lt;/li&gt;
&lt;li data-section-id=&quot;1oghz74&quot; data-start=&quot;231&quot; data-end=&quot;309&quot;&gt;&lt;strong data-start=&quot;233&quot; data-end=&quot;253&quot;&gt;Leading AI tools&lt;/strong&gt; – Exclusive access to WPP Open, our global AI platform.&lt;/li&gt;
&lt;li data-section-id=&quot;1ap2mbg&quot; data-start=&quot;421&quot; data-end=&quot;496&quot;&gt;&lt;strong data-start=&quot;423&quot; data-end=&quot;444&quot;&gt;Inclusive culture&lt;/strong&gt; – A workplace where everyone can belong and thrive.&lt;/li&gt;
&lt;li data-section-id=&quot;18t2cyd&quot; data-start=&quot;497&quot; data-end=&quot;595&quot;&gt;&lt;strong data-start=&quot;499&quot; data-end=&quot;521&quot;&gt;Career development&lt;/strong&gt; – Personalised growth plans, coaching and ongoing learning opportunities.&lt;/li&gt;
&lt;li data-section-id=&quot;1v50vn6&quot; data-start=&quot;596&quot; data-end=&quot;668&quot;&gt;&lt;strong data-start=&quot;598&quot; data-end=&quot;616&quot;&gt;Extra time off&lt;/strong&gt; – Birthday leave, Summer Fridays and loyalty leave.&lt;/li&gt;
&lt;li data-section-id=&quot;1f3wtao&quot; data-start=&quot;669&quot; data-end=&quot;770&quot;&gt;&lt;strong data-start=&quot;671&quot; data-end=&quot;692&quot;&gt;Wellbeing support&lt;/strong&gt; – Health and fitness discounts, wellbeing programs and mindfulness resources.&lt;/li&gt;
&lt;li data-section-id=&quot;1xdgi1y&quot; data-start=&quot;771&quot; data-end=&quot;849&quot;&gt;&lt;strong data-start=&quot;773&quot; data-end=&quot;804&quot;&gt;Employee Assistance Program&lt;/strong&gt; – Free, confidential counselling support.&lt;/li&gt;
&lt;li data-section-id=&quot;1m3gofr&quot; data-start=&quot;850&quot; data-end=&quot;932&quot;&gt;&lt;strong data-start=&quot;852&quot; data-end=&quot;879&quot;&gt;Recognition and rewards&lt;/strong&gt; – Celebrating great work and long-term contribution.&lt;/li&gt;
&lt;li data-section-id=&quot;185xz9j&quot; data-start=&quot;933&quot; data-end=&quot;1000&quot;&gt;&lt;strong data-start=&quot;935&quot; data-end=&quot;955&quot;&gt;Referral bonuses&lt;/strong&gt; – Earn rewards for introducing great talent.&lt;/li&gt;
&lt;li data-section-id=&quot;10adrr7&quot; data-start=&quot;1001&quot; data-end=&quot;1071&quot; data-is-last-node=&quot;&quot;&gt;&lt;strong data-start=&quot;1003&quot; data-end=&quot;1026&quot;&gt;Exclusive discounts&lt;/strong&gt; – Savings on major brands through perkSPACE&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Ogilvy, inclusivity is essential to our success. We&#39;re committed to building a workplace that embraces various perspectives, experiences, and backgrounds, knowing that diverse teams drive more impactful work.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We strongly encourage applications from Aboriginal and Torres Strait Islander peoples, Māori, people with disabilities, diverse cultural and linguistic backgrounds, all ages, genders, sexual orientations, gender identities and expressions, nationalities, and family structures.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We believe everyone thrives when they can be themselves. We provide equal opportunities and are committed to creating an inclusive environment where everyone feels valued, respected, and empowered to reach their full potential.&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you require any accessibility adjustments during the recruitment process, please let us know at &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;a href=&quot;mailto:ogv-au-careers@ogilvy.com&quot;&gt;ogv-au-careers@ogilvy.com&lt;/a&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;#LI-CO1&lt;/p&gt;

